#include <vector>
#include <algorithm>

class Solution {
public:
    int maximumProcessableQueries(std::vector<int>& nums, std::vector<int>& queries) {
        int n = nums.size();
        int m = queries.size();
        std::vector<std::vector<int>> f(n, std::vector<int>(n, 0));
        for (int i = 0; i < n; ++i) {
            for (int j = n - 1; j >= i; --j) {
                if (i > 0) {
                    f[i][j] = std::max(f[i][j], f[i - 1][j] + (nums[i - 1] >= queries[f[i - 1][j]] ? 1 : 0));
                }
                if (j + 1 < n) {
                    f[i][j] = std::max(f[i][j], f[i][j + 1] + (nums[j + 1] >= queries[f[i][j + 1]] ? 1 : 0));
                }
                if (f[i][j] == m) return m;
            }
        }
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            ans = std::max(ans, f[i][i] + (nums[i] >= queries[f[i][i]] ? 1 : 0));
        }
        return ans;
    }
};

